-- Resources content for pause shortening in pieces and word-tap trim on excerpt cards (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-piece-trim-and-pauses',
  p_tool_key => 'transcription',
  p_title => 'Trim a clip and shorten its pauses',
  p_summary => 'Set where a clip starts and ends in a piece, and cut its long pauses down.',
  p_screen_keys => array['sourcework.piece'],
  p_sort_order => 19,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim sets where a clip starts and ends in a piece. Pauses shortens the long gaps inside it. Both change only this piece unless you choose otherwise."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip"}]},{"type":"paragraph","content":[{"type":"text","text":"On an excerpt block, open the "},{"type":"text","text":"⋮","marks":[{"type":"bold"}]},{"type":"text","text":" menu and choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":". The clip's words appear with a few words of transcript either side. Tap a word to move the start or end to it, whichever is nearer, or use the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays the clip as it is now."}]},{"type":"paragraph","content":[{"type":"text","text":"The excerpt's own trim buttons on the transcript screen work the same way: choose "},{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt card and tap a word to move its start or end."}]},{"type":"paragraph","content":[{"type":"text","text":"By default the trim applies to this piece only. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shorten long pauses"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick a setting. "},{"type":"text","text":"Long pauses only","marks":[{"type":"bold"}]},{"type":"text","text":" looks for gaps over a second, "},{"type":"text","text":"Standard","marks":[{"type":"bold"}]},{"type":"text","text":" over 0.7 seconds and "},{"type":"text","text":"Tight","marks":[{"type":"bold"}]},{"type":"text","text":" over half a second. Each pause is cut down rather than removed, leaving a short beat so the speaker doesn't sound clipped."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Find pauses","marks":[{"type":"bold"}]},{"type":"text","text":". Each one is marked between the words with how much it would save, for example ⏸ 1.4s."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" to hear the clip with those pauses skipped."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Remove these pauses","marks":[{"type":"bold"}]},{"type":"text","text":" to apply them, or "},{"type":"text","text":"Cancel","marks":[{"type":"bold"}]},{"type":"text","text":" to leave the clip as it is."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Shortened pauses show as −1.4s in the words, the block says how many it has, and the piece's length updates. "},{"type":"text","text":"Put the pauses back","marks":[{"type":"bold"}]},{"type":"text","text":" restores the clip. Pauses are found from the transcript's word timings, so a line with no timings has nothing to find. Pauses are kept per piece; the same excerpt in another piece is not changed."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-12-sourcework-piece-pauses',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-12',
  p_title => 'Sourcework: shorten long pauses in a piece',
  p_guide_slugs => array['sourcework-piece-trim-and-pauses', 'sourcework-pieces', 'sourcework-transcript-and-excerpts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim in a piece now has a Pauses section. Choose a setting, find the long gaps in a clip, hear the result with Play as cut, and shorten them for that piece only. The piece's length updates, and Put the pauses back undoes it. On the transcript screen, Trim on an excerpt card now shows the clip's words, so you can tap a word to move its start or end instead of nudging by milliseconds."}]}]}$body$
);
